<script setup lang="ts">
import {ref} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:unknown)=>Promise<any>}>();
const emit=defineEmits<{(event:'imported'):void}>();
const dialog=ref<HTMLDialogElement|null>(null),fileInput=ref<HTMLInputElement|null>(null),busy=ref(false),error=ref(''),notice=ref(''),bundle=ref<any>(null),preview=ref<any>(null),fileName=ref('');
function download(data:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportFile(){busy.value=true;error.value='';try{download(await props.api('/settings-transfer/export'),'utblib-settings.json');notice.value='Сохранённые настройки выгружены. Перенесите этот файл на сервер через кнопку «Импорт настроек».';}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function choose(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;error.value='';notice.value='';preview.value=null;bundle.value=null;fileName.value=file.name;dialog.value?.showModal();busy.value=true;try{if(file.size>20*1024*1024)throw Error('Файл больше 20 МБ.');const data=JSON.parse(await file.text());const result=await props.api('/settings-transfer/preview','POST',data);bundle.value=data;preview.value=result;}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function apply(){if(!preview.value||busy.value)return;busy.value=true;error.value='';try{
 const backup=await props.api('/settings-transfer/export');download(backup,`utblib-settings-before-import-${Date.now()}.json`);
 await props.api('/settings-transfer/apply','POST',{bundle:bundle.value,expected_state:preview.value.expected_state,expected_bundle:preview.value.expected_bundle});
 notice.value='Настройки перенесены. Справочники с автопополнением заполнены из каталога сервера.';preview.value=null;bundle.value=null;dialog.value?.close();emit('imported');
 }catch(e){error.value=e instanceof Error?e.message:String(e);preview.value=null;}finally{busy.value=false;}}
</script>
<template>
<section class="card settings-transfer"><div class="section-heading"><h2>Перенос настроек</h2><p>Экспортируются сохранённые настройки всех типов документов, порядок полей и значения справочников с пояснениями. Сначала сохраните изменения рабочего листа.</p></div><div class="modal-actions"><button type="button" :disabled="busy" @click="exportFile">Экспорт настроек</button><button type="button" :disabled="busy" @click="fileInput?.click()">Импорт настроек</button><input ref="fileInput" type="file" accept=".json,application/json" aria-label="Файл настроек" hidden @change="choose"></div><p v-if="notice" role="status">{{notice}}</p><p v-if="error&&!dialog?.open" role="alert" class="inline-error">{{error}}</p></section>
<dialog ref="dialog" class="modal card transfer-dialog" aria-labelledby="transfer-title" @cancel="busy&&$event.preventDefault()">
<h2 id="transfer-title">Проверка переноса настроек</h2><p>{{fileName}}</p><p v-if="busy" role="status">Обработка…</p><p v-if="error" class="inline-error" role="alert">{{error}}</p>
<template v-if="preview"><p>Типы сопоставляются по точному названию. Для совпавших типов рабочий лист будет заменён настройками из файла; отсутствующие типы будут созданы. Остальные типы сохранятся.</p><p>Значения справочников объединяются. Существующие непустые пояснения сервера сохраняются. ФИО операторов берутся из пользователей сервера.</p><div class="table-wrap"><table><thead><tr><th>Тип документа</th><th>Действие</th><th>Полей: было → станет</th><th>Новых значений</th><th>Пояснений сервера сохранится при конфликте</th></tr></thead><tbody><tr v-for="t in preview.types" :key="t.name"><td>{{t.name}}</td><td>{{t.action==='create'?'Создать':'Заменить настройки'}}<details><summary>Поля и порядок после переноса</summary><ol><li v-for="c in t.config" :key="c.tag"><b>{{c.tag}}</b> {{c.label}} {{c.required?'· обязательное':''}}<span v-if="c.subfields.length"> · подполя: {{c.subfields.join(', ')}}</span><div v-for="(v,code) in c.vocabularies" :key="code">${{code}}: справочник; автопополнение {{v.auto_add?'вкл.':'выкл.'}}, редактирование {{v.allow_edit?'вкл.':'выкл.'}}</div></li></ol></details></td><td>{{t.fields_before}} → {{t.fields_after}}</td><td>{{t.entries_added}}</td><td>{{t.labels_preserved}}</td></tr></tbody></table></div><p>Каталог, экземпляры, поступления и пользователи не изменяются. При применении будет скачана резервная копия текущих настроек. Автопополнение дополнительно соберёт значения из существующего каталога.</p></template>
<div class="modal-actions"><button type="button" :disabled="busy" @click="dialog?.close()">Закрыть</button><button type="button" class="primary" :disabled="busy||!preview" @click="apply">Применить настройки</button></div>
</dialog>
</template>
<style scoped>.settings-transfer{margin-bottom:20px}.transfer-dialog{width:min(1000px,95vw);max-width:95vw}.transfer-dialog p{margin:12px 0}</style>
